package de.lazytv.pro.catalog;
import android.app.*;import android.os.*;import android.content.Intent;import android.text.*;import android.view.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;import de.lazytv.pro.R;import de.lazytv.pro.activation.ActivationGuard;
/** Managed on-demand browsing reuses the native movie and episode players. */
public final class ManagedCatalogActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private long generation;private String server;private CatalogType type;private Catalog catalog;private Series selectedSeries;private List<StreamItem> episodeRows;private List<StreamItem> shown=new ArrayList<>();private GridView list;private TextView status,title,breadcrumb;private EditText search;private CatalogAdapter adapter;
 protected void onCreate(Bundle state){super.onCreate(state);if(!ActivationGuard.enforce(this))return;server=getIntent().getStringExtra("server_name");if(server==null){finish();return;}type="SERIES".equals(getIntent().getStringExtra("catalog_type"))?CatalogType.SERIES:CatalogType.MOVIES;setContentView(R.layout.activity_catalog);loadNavArtwork();list=findViewById(R.id.catalog_list);status=findViewById(R.id.catalog_status);title=findViewById(R.id.catalog_title);breadcrumb=findViewById(R.id.catalog_breadcrumb);search=findViewById(R.id.catalog_search);title.setText(server);adapter=new CatalogAdapter();adapter.resumeProvider(this,"MANAGED_BACKEND|"+server);list.setAdapter(adapter);int width=(int)(getResources().getDisplayMetrics().widthPixels/getResources().getDisplayMetrics().density);list.setNumColumns(width<700?2:width<1100?3:4);list.setOnItemClickListener((a,v,n,id)->{if(n<shown.size())open(shown.get(n));});list.setOnItemLongClickListener((a,v,n,id)->{if(n>=shown.size())return false;boolean added=new FavoritesStore(this).toggle("MANAGED_BACKEND|"+server,shown.get(n));Toast.makeText(this,added?"U shtua te Favorites":"U hoq nga Favorites",Toast.LENGTH_SHORT).show();return true;});findViewById(R.id.tab_live).setOnClickListener(v->{finish();});findViewById(R.id.tab_movies).setOnClickListener(v->{type=CatalogType.MOVIES;load();});findViewById(R.id.tab_series).setOnClickListener(v->{type=CatalogType.SERIES;load();});findViewById(R.id.tab_favorites).setOnClickListener(v->{if(catalog!=null){shown=new FavoritesStore(this).filter("MANAGED_BACKEND|"+server,catalog.items);adapter.set(shown);}});findViewById(R.id.continue_watching).setVisibility(View.GONE);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int a,int b,int c){filter();}public void afterTextChanged(Editable e){}});load();}
 private void loadNavArtwork(){try{java.io.InputStream in=getAssets().open("home_tiles.jpg.b64");java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=in.read(buf))>0)out.write(buf,0,n);in.close();byte[] raw=android.util.Base64.decode(out.toString("UTF-8").trim(),android.util.Base64.DEFAULT);android.graphics.Bitmap sheet=android.graphics.BitmapFactory.decodeByteArray(raw,0,raw.length);if(sheet==null)return;int cw=sheet.getWidth()/4,ch=sheet.getHeight()/2;int[] ids={R.id.tab_live,R.id.tab_movies,R.id.tab_series};for(int i=0;i<ids.length;i++)((ImageButton)findViewById(ids[i])).setImageBitmap(android.graphics.Bitmap.createBitmap(sheet,i*cw,0,cw,ch));}catch(Exception ignored){}}
 private void load(){long ticket=++generation;CatalogType requested=type;selectedSeries=null;episodeRows=null;catalog=null;shown.clear();adapter.set(shown);status.setText("Duke lexuar "+requested+"…");findViewById(R.id.catalog_progress).setVisibility(View.VISIBLE);worker.execute(()->{try{Catalog result=new ManagedBackendCatalogSource(this).loadType(server,requested);runOnUiThread(()->{if(!valid(ticket))return;catalog=result;findViewById(R.id.catalog_progress).setVisibility(View.GONE);filter();});}catch(Exception error){runOnUiThread(()->{if(valid(ticket)){findViewById(R.id.catalog_progress).setVisibility(View.GONE);status.setText("Katalogu managed nuk mund të lexohet");}});}});}
 private boolean valid(long ticket){return ticket==generation&&!isFinishing()&&!isDestroyed();}
 private void filter(){if(catalog==null)return;String q=search.getText().toString().trim().toLowerCase(Locale.ROOT);shown=new ArrayList<>();for(StreamItem item:episodeRows==null?catalog.items:episodeRows)if(item.name.toLowerCase(Locale.ROOT).contains(q))shown.add(item);adapter.set(shown);breadcrumb.setText(server+" › "+type.name());status.setText(shown.isEmpty()?"Nuk ka "+(type==CatalogType.MOVIES?"filma individualë":"seriale/sezone/episode")+" të vlefshme në këtë burim":shown.size()+" hyrje");}
 private void open(StreamItem item){if(item.type==CatalogType.MOVIES){MovieDetailActivity.open(this,"MANAGED_BACKEND|"+server,item,null,"");return;}if(item instanceof Series){selectedSeries=(Series)item;long ticket=++generation;status.setText("Duke lexuar episodet…");worker.execute(()->{try{SeriesDetails details=new ManagedBackendCatalogSource(this).loadSeries(server,(Series)item);runOnUiThread(()->{if(!valid(ticket))return;if(details.seasons.isEmpty()){status.setText("Episodet nuk disponohen në burim");return;}String[] labels=new String[details.seasons.size()];for(int n=0;n<labels.length;n++)labels[n]=details.seasons.get(n).title;new AlertDialog.Builder(this).setTitle(item.name+" • Seasons").setItems(labels,(dialog,n)->{Season season=details.seasons.get(n);episodeRows=new ArrayList<>(details.episodes.getOrDefault(season.number,Collections.emptyList()));shown=new ArrayList<>(episodeRows);search.setText("");adapter.set(shown);breadcrumb.setText(item.name+" › "+season.title+" › Episodes");status.setText(shown.isEmpty()?"Episodet nuk disponohen në burim":shown.size()+" episode");}).show();});}catch(Exception error){runOnUiThread(()->{if(valid(ticket))status.setText("Episodet nuk mund të ngarkohen");});}});return;}if(item instanceof Episode){long ticket=++generation;worker.execute(()->{try{ResolvedStream stream=ManagedProviderContext.resolve(this,item,true);runOnUiThread(()->{if(valid(ticket))de.lazytv.pro.player.PlayerLauncher.playEpisode(this,"MANAGED_BACKEND|"+server,(Episode)item,stream,selectedSeries==null?"":selectedSeries.name,true);});}catch(Exception error){runOnUiThread(()->{if(valid(ticket))status.setText("Stream-i i episodit nuk mund të përgatitet");});}});}}
 public void onBackPressed(){if(selectedSeries!=null){selectedSeries=null;episodeRows=null;filter();return;}super.onBackPressed();}protected void onDestroy(){generation++;worker.shutdownNow();if(adapter!=null)adapter.close();super.onDestroy();}
}
